{
  "summary": "The old harness cannot reach the new key-specific wrong-type diagnostics. It also has preexisting gaps in typed extraction, nested unpacking, strict object validation, and reference-counted extraction.",
  "coverage_complete": false,
  "coverage_evidence": [],
  "claims": [
    {
      "claim_id": "keyed_wrong_type_diagnostic",
      "necessary": "yes",
      "necessity_reason": "A valid object can contain a member whose type conflicts with a typed unpack format. The changed unpack operation reports that member's key, but the harness's fixed formats never request typed validation of an object member.",
      "before": {
        "requirement": "For a mismatched typed object member, report the expected and actual types without the member key.",
        "applicability": "required",
        "harness_status": "unsat",
        "reason": "The old harness only unpacks object members with the generic o format, so it cannot trigger this typed mismatch.",
        "source_evidence": [
          {
            "unit_id": "u-fb2b0902161308341cab",
            "start_line": 528,
            "end_line": 555,
            "role": "primary",
            "dependency_reason": ""
          },
          {
            "unit_id": "u-9cefb4424b22803c6417",
            "start_line": 687,
            "end_line": 692,
            "role": "dependency",
            "dependency_reason": "The string format rejects a non-string value and produces the earlier wrong-type message."
          }
        ]
      },
      "after": {
        "requirement": "For a mismatched typed object member, report the expected and actual types with that member's key.",
        "applicability": "required",
        "harness_status": "unsat",
        "reason": "The changed code passes the object key into typed validation, but the harness still selects only generic o for object members.",
        "source_evidence": [
          {
            "unit_id": "u-492d1cbf05366c92bf62",
            "start_line": 530,
            "end_line": 557,
            "role": "primary",
            "dependency_reason": ""
          },
          {
            "unit_id": "u-6ea6a2b1b78051d20b1c",
            "start_line": 690,
            "end_line": 696,
            "role": "dependency",
            "dependency_reason": "The typed string mismatch appends the supplied key to the wrong-type message."
          }
        ]
      },
      "same_blocker": "yes",
      "harness_evidence": [
        {
          "unit_id": "u-3fb700706fd6be77b194",
          "start_line": 57,
          "end_line": 83,
          "role": "primary",
          "dependency_reason": ""
        }
      ],
      "comparison_reason": "The same fixed format selection prevents typed member mismatches on both sides; the key-bearing diagnostic is the changed part of that behavior.",
      "missing_information": [],
      "change_ids": ["g0003", "g0006", "g0007", "g0008", "g0009", "g0010", "g0011", "g0012"]
    },
    {
      "claim_id": "typed_scalar_unpack",
      "necessary": "yes",
      "necessity_reason": "Typed scalar extraction and validation are supported behaviors of json_unpack for values the JSON input can supply. The fixed formats select generic o instead.",
      "before": {
        "requirement": "Reach typed scalar extraction or validation with a matching or mismatching scalar value.",
        "applicability": "required",
        "harness_status": "unsat",
        "reason": "No harness call uses the s, i, I, b, f, F, or n unpack format.",
        "source_evidence": [
          {
            "unit_id": "u-9cefb4424b22803c6417",
            "start_line": 687,
            "end_line": 797,
            "role": "primary",
            "dependency_reason": ""
          }
        ]
      },
      "after": {
        "requirement": "Reach typed scalar extraction or validation with a matching or mismatching scalar value.",
        "applicability": "required",
        "harness_status": "unsat",
        "reason": "The scalar format capabilities remain, and the same fixed calls cannot select them.",
        "source_evidence": [
          {
            "unit_id": "u-6ea6a2b1b78051d20b1c",
            "start_line": 690,
            "end_line": 806,
            "role": "primary",
            "dependency_reason": ""
          }
        ]
      },
      "same_blocker": "yes",
      "harness_evidence": [
        {
          "unit_id": "u-3fb700706fd6be77b194",
          "start_line": 70,
          "end_line": 83,
          "role": "primary",
          "dependency_reason": ""
        }
      ],
      "comparison_reason": "Both source versions support typed scalar formats; the old harness's format literals exclude them on both sides.",
      "missing_information": [],
      "change_ids": ["g0006", "g0007", "g0008", "g0009", "g0010", "g0011", "g0012"]
    },
    {
      "claim_id": "nested_unpack",
      "necessary": "yes",
      "necessity_reason": "The unpack format supports recursive object and array extraction, and valid JSON input can contain either nested structure. The harness uses generic o for members and elements.",
      "before": {
        "requirement": "Reach recursive unpacking of an object or array contained in an input value.",
        "applicability": "required",
        "harness_status": "unsat",
        "reason": "Its fixed formats contain no nested object or array format.",
        "source_evidence": [
          {
            "unit_id": "u-9cefb4424b22803c6417",
            "start_line": 679,
            "end_line": 685,
            "role": "primary",
            "dependency_reason": ""
          },
          {
            "unit_id": "u-fb2b0902161308341cab",
            "start_line": 542,
            "end_line": 555,
            "role": "dependency",
            "dependency_reason": "Object member values are passed recursively to unpack when the format requests it."
          }
        ]
      },
      "after": {
        "requirement": "Reach recursive unpacking of an object or array contained in an input value.",
        "applicability": "required",
        "harness_status": "unsat",
        "reason": "Recursive dispatch remains available, but the same harness formats select generic o at member and element positions.",
        "source_evidence": [
          {
            "unit_id": "u-6ea6a2b1b78051d20b1c",
            "start_line": 682,
            "end_line": 688,
            "role": "primary",
            "dependency_reason": ""
          },
          {
            "unit_id": "u-492d1cbf05366c92bf62",
            "start_line": 544,
            "end_line": 557,
            "role": "dependency",
            "dependency_reason": "Object member values are passed recursively to unpack with their key."
          }
        ]
      },
      "same_blocker": "yes",
      "harness_evidence": [
        {
          "unit_id": "u-3fb700706fd6be77b194",
          "start_line": 70,
          "end_line": 83,
          "role": "primary",
          "dependency_reason": ""
        }
      ],
      "comparison_reason": "The unchanged lack of a nested format prevents recursive unpacking before and after the change.",
      "missing_information": [],
      "change_ids": ["g0003", "g0004", "g0005", "g0006"]
    },
    {
      "claim_id": "strict_object_unpack",
      "necessary": "yes",
      "necessity_reason": "Object unpacking supports an explicit strict format that rejects unconsumed object members. Valid input can contain such extra members, but the harness's object format omits strict selection.",
      "before": {
        "requirement": "Reach strict object validation for an input object with an unconsumed member.",
        "applicability": "required",
        "harness_status": "unsat",
        "reason": "The harness uses {s?o} without ! and json_unpack supplies zero flags.",
        "source_evidence": [
          {
            "unit_id": "u-fb2b0902161308341cab",
            "start_line": 516,
            "end_line": 519,
            "role": "primary",
            "dependency_reason": ""
          },
          {
            "unit_id": "u-fb2b0902161308341cab",
            "start_line": 561,
            "end_line": 598,
            "role": "dependency",
            "dependency_reason": "Strict selection checks for members left unpacked and returns an error."
          }
        ]
      },
      "after": {
        "requirement": "Reach strict object validation for an input object with an unconsumed member.",
        "applicability": "required",
        "harness_status": "unsat",
        "reason": "The strict object capability remains, while the same object format and zero flags still cannot select it.",
        "source_evidence": [
          {
            "unit_id": "u-492d1cbf05366c92bf62",
            "start_line": 518,
            "end_line": 521,
            "role": "primary",
            "dependency_reason": ""
          },
          {
            "unit_id": "u-492d1cbf05366c92bf62",
            "start_line": 563,
            "end_line": 600,
            "role": "dependency",
            "dependency_reason": "Strict selection checks for members left unpacked and returns an error."
          }
        ]
      },
      "same_blocker": "yes",
      "harness_evidence": [
        {
          "unit_id": "u-3fb700706fd6be77b194",
          "start_line": 70,
          "end_line": 77,
          "role": "primary",
          "dependency_reason": ""
        },
        {
          "unit_id": "u-519c5b4abd7f7596d7f9",
          "start_line": 937,
          "end_line": 945,
          "role": "dependency",
          "dependency_reason": "The selected json_unpack wrapper passes zero flags."
        }
      ],
      "comparison_reason": "The explicit strict object path is supported on both sides, and the same object format omits it.",
      "missing_information": [],
      "change_ids": ["g0002"]
    },
    {
      "claim_id": "retained_reference_unpack",
      "necessary": "yes",
      "necessity_reason": "The O format has a distinct ownership contract: it increments the extracted value's reference count. The harness only requests borrowed o values.",
      "before": {
        "requirement": "Reach O-format extraction with a valid JSON value and manage the acquired reference.",
        "applicability": "required",
        "harness_status": "unsat",
        "reason": "No harness format contains O.",
        "source_evidence": [
          {
            "unit_id": "u-9cefb4424b22803c6417",
            "start_line": 799,
            "end_line": 811,
            "role": "primary",
            "dependency_reason": ""
          }
        ]
      },
      "after": {
        "requirement": "Reach O-format extraction with a valid JSON value and manage the acquired reference.",
        "applicability": "required",
        "harness_status": "unsat",
        "reason": "The ownership behavior remains, and no harness format contains O.",
        "source_evidence": [
          {
            "unit_id": "u-6ea6a2b1b78051d20b1c",
            "start_line": 808,
            "end_line": 820,
            "role": "primary",
            "dependency_reason": ""
          }
        ]
      },
      "same_blocker": "yes",
      "harness_evidence": [
        {
          "unit_id": "u-3fb700706fd6be77b194",
          "start_line": 70,
          "end_line": 83,
          "role": "primary",
          "dependency_reason": ""
        }
      ],
      "comparison_reason": "Both versions distinguish O from o by reference ownership; the old harness selects only o.",
      "missing_information": [],
      "change_ids": ["g0006"]
    }
  ],
